// tsc --noEmit's CSS-module typing normally comes from next-env.d.ts's
// `/// <reference types="next" />`, but next-env.d.ts is gitignored and
// only auto-generated by `next dev`/`next build` — CI's typecheck step
// runs before build, against a fresh checkout with neither file present,
// so it fails with "Cannot find module '*.module.css'" even though a
// sandbox that has already run `next dev`/`next build` (and so already has
// next-env.d.ts on disk) won't reproduce the failure locally. Committing
// this ambient declaration — identical in shape to next/types/global.d.ts's
// own — makes typecheck self-sufficient on a clean checkout.
declare module "*.module.css" {
  const classes: { readonly [key: string]: string };
  export default classes;
}

declare module "*.css";
